"""
launcher.py — PRH EPUB 3 Automation Studio Launcher
Fetches latest code from GitHub (mopvps/eAyesha_extractor) and launches local Flask web tool.
"""

import os
import sys
import threading
import webbrowser
import time
import urllib.request
import urllib.error
from pathlib import Path
import tkinter as tk
from PIL import Image, ImageTk

LOGO_B64 = ""

# ── GitHub Config ──────────────────────────────────────────────────────────────
GITHUB_USER   = "mopvps"
GITHUB_REPO   = "eAyesha_extractor"
GITHUB_BRANCH = "main"
RAW_BASE      = f"https://raw.githubusercontent.com/{GITHUB_USER}/{GITHUB_REPO}/{GITHUB_BRANCH}"

TRACKED_FILES = [
    "app.py",
    "chapter.py",
    "fm.py",
    "back.py",
    "templates/index.html",
    "static/css/style.css",
    "static/js/main.js",
    "static/img/logo.webp",
]

# ── Paths ──────────────────────────────────────────────────────────────────────
if getattr(sys, 'frozen', False):
    EXE_DIR = Path(sys.executable).parent
else:
    EXE_DIR = Path(__file__).parent

APP_DIR = EXE_DIR / "app_files"

# ── Theme (Light Blue & Crisp White) ──────────────────────────────────────────
T = {
    "bg":          "#F0F6FC",
    "surface":     "#FFFFFF",
    "surface2":    "#E0F2FE",
    "border":      "#BAE6FD",
    "accent":      "#0284C7",
    "accent_dark": "#0369A1",
    "pass":        "#16A34A",
    "fail":        "#DC2626",
    "warn":        "#D97706",
    "text":        "#0F172A",
    "text2":       "#334155",
    "muted":       "#64748B",
}

SERVER_URL = "http://127.0.0.1:5000"


# ══════════════════════════════════════════════════════════════════════════════
# GitHub API Downloader
# ══════════════════════════════════════════════════════════════════════════════

def ensure_dirs():
    for f in TRACKED_FILES:
        (APP_DIR / f).parent.mkdir(parents=True, exist_ok=True)


def fetch_via_raw(rel_path: str):
    """
    Fetch file content via raw.githubusercontent.com.
    Returns raw bytes or None on failure. No rate limit, no token required.
    """
    url = f"{RAW_BASE}/{rel_path}"
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "EpubAyesha-Launcher"}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return r.read()
    except Exception as e:
        print(f"[RAW] Error for {rel_path}: {e}")
        return None


def download_all(log_fn, progress_fn):
    total   = len(TRACKED_FILES)
    success = 0
    failed  = 0

    log_fn("📡  Fetching latest files from GitHub...", T["muted"])

    for i, rel_path in enumerate(TRACKED_FILES):
        local_path = APP_DIR / rel_path

        content = fetch_via_raw(rel_path)

        if content:
            local_path.write_bytes(content)
            log_fn(f"  ✓  {rel_path}", T["pass"])
            success += 1
        else:
            if local_path.exists():
                log_fn(f"  ⚠  {rel_path}  (using local cached copy)", T["warn"])
            else:
                log_fn(f"  ✗  {rel_path}  FAILED — no local copy!", T["fail"])
                failed += 1

        progress_fn(int((i + 1) / total * 60))

    if failed:
        log_fn(f"⚠  {failed} file(s) could not be fetched", T["warn"])
    else:
        log_fn(f"✅  All {success} files verified (latest commit)!", T["pass"])

    return failed == 0


# ══════════════════════════════════════════════════════════════════════════════
# Tkinter UI
# ══════════════════════════════════════════════════════════════════════════════

class LauncherApp:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("PRH EPUB 3 Studio — Launcher")
        self.root.resizable(False, False)
        self.root.configure(bg=T["bg"])
        self._center(480, 580)
        self._build_ui()
        self.root.protocol("WM_DELETE_WINDOW", self._quit)

    def _center(self, w, h):
        self.root.update_idletasks()
        sw = self.root.winfo_screenwidth()
        sh = self.root.winfo_screenheight()
        x = int((sw - w) / 2)
        y = int((sh - h) / 2)
        self.root.geometry(f"{w}x{h}+{x}+{y}")

    def _build_ui(self):
        # ── Header ────────────────────────────────────────────────────────────
        header = tk.Frame(self.root, bg=T["surface"], height=65,
                          highlightbackground=T["border"], highlightthickness=1)
        header.pack(fill="x")
        header.pack_propagate(False)

        self._load_logo(header)

        title_frame = tk.Frame(header, bg=T["surface"])
        title_frame.pack(side="left", padx=(16, 0), pady=12)

        tk.Label(title_frame, text="PRH EPUB 3 Studio",
                 bg=T["surface"], fg=T["accent"],
                 font=("Segoe UI", 13, "bold")
                 ).pack(anchor="w")
        tk.Label(title_frame, text="Spec 8.0 Automation Suite",
                 bg=T["surface"], fg=T["muted"],
                 font=("Segoe UI", 8)
                 ).pack(anchor="w")

        # ── Status ────────────────────────────────────────────────────────────
        sf = tk.Frame(self.root, bg=T["bg"], pady=8)
        sf.pack(fill="x")

        self.status_dot = tk.Label(sf, text="●", bg=T["bg"],
                                   fg=T["warn"], font=("Segoe UI", 11))
        self.status_dot.pack(side="left", padx=(20, 6))

        self.status_lbl = tk.Label(sf, text="Initializing launcher...",
                                   bg=T["bg"], fg=T["text2"],
                                   font=("Segoe UI", 10, "bold"))
        self.status_lbl.pack(side="left")

        # ── Bottom Fixed Panel (Pack first from bottom so it never clips!) ─────
        bottom_panel = tk.Frame(self.root, bg=T["bg"])
        bottom_panel.pack(side="bottom", fill="x", padx=20, pady=(0, 10))

        tk.Label(bottom_panel,
                 text=f"github.com/{GITHUB_USER}/{GITHUB_REPO}",
                 bg=T["bg"], fg=T["muted"], font=("Segoe UI", 8)
                 ).pack(side="bottom", pady=(6, 0))

        bf = tk.Frame(bottom_panel, bg=T["bg"])
        bf.pack(side="bottom", fill="x", pady=(8, 0))

        self.open_btn = tk.Button(bf, text="🌐  Open in Browser",
                                  bg=T["accent"], fg="#FFFFFF",
                                  font=("Segoe UI", 10, "bold"),
                                  relief="flat", bd=0,
                                  padx=18, pady=8, cursor="hand2",
                                  activebackground=T["accent_dark"],
                                  activeforeground="#FFFFFF",
                                  state="disabled",
                                  command=self._open_browser)
        self.open_btn.pack(side="left", fill="x", expand=True, padx=(0, 8))

        tk.Button(bf, text="✕  Quit",
                  bg=T["surface2"], fg=T["accent_dark"],
                  font=("Segoe UI", 10, "bold"), relief="flat", bd=0,
                  padx=18, pady=8, cursor="hand2",
                  command=self._quit
                  ).pack(side="right")

        # Progress bar
        pf = tk.Frame(bottom_panel, bg=T["bg"])
        pf.pack(side="bottom", fill="x", pady=(6, 4))

        self.prog_canvas = tk.Canvas(pf, height=6, bg="#E2E8F0",
                                     highlightthickness=0, bd=0)
        self.prog_canvas.pack(fill="x")
        self.prog_bar = self.prog_canvas.create_rectangle(
            0, 0, 0, 6, fill=T["accent"], width=0)

        # ── Log box (takes remaining middle space safely) ───────────────────────
        lf = tk.Frame(self.root, bg=T["surface"],
                      highlightbackground=T["border"], highlightthickness=1)
        lf.pack(fill="both", expand=True, padx=20, pady=(0, 8))

        self.log = tk.Text(lf, bg=T["surface"], fg=T["text"],
                           font=("Consolas", 9), relief="flat", bd=0,
                           state="disabled", wrap="word",
                           padx=12, pady=10, cursor="arrow")
        self.log.pack(fill="both", expand=True)

        self.log.tag_config("pass",   foreground=T["pass"])
        self.log.tag_config("fail",   foreground=T["fail"])
        self.log.tag_config("warn",   foreground=T["warn"])
        self.log.tag_config("accent", foreground=T["accent"])
        self.log.tag_config("muted",  foreground=T["muted"])
        self.log.tag_config("text",   foreground=T["text"])

    def _load_logo(self, header):
        try:
            import base64
            from io import BytesIO
            img_data = base64.b64decode(LOGO_B64)
            img = Image.open(BytesIO(img_data)).convert("RGBA")
            ratio = 36 / img.height
            img = img.resize((max(1, int(img.width * ratio)), 36), Image.LANCZOS)
            self.logo_img = ImageTk.PhotoImage(img)
            tk.Label(header, image=self.logo_img, bg=T["surface"]
                     ).pack(side="right", padx=(0, 16), pady=12)
        except Exception as e:
            print(f"[LOGO] skipped: {e}")

    # ── Helpers ───────────────────────────────────────────────────────────────

    def _log(self, msg, color=None):
        tag = {T["pass"]: "pass", T["fail"]: "fail", T["warn"]: "warn",
               T["accent"]: "accent", T["muted"]: "muted"}.get(color, "text")
        def _do():
            self.log.configure(state="normal")
            self.log.insert("end", msg + "\n", tag)
            self.log.see("end")
            self.log.configure(state="disabled")
        self.root.after(0, _do)

    def _set_status(self, text, color):
        self.root.after(0, lambda: [
            self.status_lbl.configure(text=text),
            self.status_dot.configure(fg=color)
        ])

    def _set_progress(self, pct):
        def _do():
            w = self.prog_canvas.winfo_width()
            self.prog_canvas.coords(self.prog_bar, 0, 0, w * pct / 100, 6)
        self.root.after(0, _do)

    def _open_browser(self):
        webbrowser.open(SERVER_URL)

    def _quit(self):
        os._exit(0)

    def _enable_open(self):
        self.root.after(0, lambda: self.open_btn.configure(state="normal"))

    # ── Main Sequence ─────────────────────────────────────────────────────────

    def _sequence(self):
        # 1. Download via raw URLs
        ensure_dirs()
        self._set_status("Fetching latest files from GitHub...", T["warn"])
        ok = download_all(self._log, self._set_progress)

        if not ok:
            self._set_status("Using cached files", T["warn"])

        # 2. Start Flask
        self._set_progress(70)
        self._set_status("Starting server...", T["warn"])
        self._log("🚀  Starting Flask server...", T["accent"])

        try:
            sys.path.insert(0, str(APP_DIR))
            os.chdir(APP_DIR)
            from app import app as flask_app

            self._set_progress(100)
            self._set_status(f"Running  •  {SERVER_URL}", T["pass"])
            self._enable_open()
            self._log(f"✅  Server ready → {SERVER_URL}", T["pass"])

            threading.Thread(
                target=lambda: (time.sleep(1.2), webbrowser.open(SERVER_URL)),
                daemon=True
            ).start()

            flask_app.run(host="127.0.0.1", port=5000,
                          debug=False, use_reloader=False)

        except Exception as e:
            self._log(f"❌  {e}", T["fail"])
            self._set_status("Server error!", T["fail"])

    def run(self):
        threading.Thread(target=self._sequence, daemon=True).start()
        self.root.mainloop()


# ══════════════════════════════════════════════════════════════════════════════
if __name__ == "__main__":
    LauncherApp().run()
